import { useState, useEffect } from 'react';
import {
  Box,
  Button,
  Grid,
  IconButton,
  Typography,
  Container,
  CssBaseline
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import LogoutIcon from '@mui/icons-material/Logout';
import PupilModalDialog from './PupilModal.js';
import RemoveIcon from '@mui/icons-material/Remove';
import DownloadIcon from '@mui/icons-material/Download';
import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";
import {
  doc,
  getDoc,
  updateDoc,
  getDocs,
  collection
} from "firebase/firestore";
import { db } from "../firebase.js";
import {
  Table, TableBody, TableCell, TableContainer,
  TableHead, TableRow, Paper
} from "@mui/material";

export default function Dashboard({ onLogout, classCode, setClassCode, adminMode }) {
  const [modalOpen, setModalOpen] = useState(false);
  const [pupilModalOpen, setPupilModalOpen] = useState(false);
  const [pupils, setPupils] = useState([]);
  const [sign, setSign] = useState("");
  const [classes, setClasses] = useState([]);
  const notoFontBase64 = ""; 

  useEffect(() => {
  const fetchData = async () => {
    if(!adminMode) {
      const docSnap = await getDoc(doc(db, "shicheck", `${classCode.toLowerCase()}`));    
      const data = docSnap.data();
      
      const newPupils = [];
      const names = data.names;
      const presence = data.present;
      for(let i = 0; i < names.length; i++) {
        newPupils[i] = {name: names[i], present: presence[i]}
      }
      setPupils(newPupils);
    } else {
      const querySnapshot = await getDocs(collection(db, "shicheck"));

      const data = querySnapshot.docs.flatMap(doc => {
        const d = doc.data();
        return d.names.map((name, i) => ({
          id: doc.data().name,
          name,
          present: d.present[i]
        }));
      });
      setClasses(data);
    }
  };

  fetchData();

  return;
}, []);


  const handleButtonClick = (i) => {
    const newPupils = pupils.map((pupil, index) =>
      index === i ? { ...pupil, present: !pupil.present } : pupil
    );
    setNewPupils(newPupils);
  };
  const setNewPupils = async (newPupils) => {
    setPupils(newPupils);
    let newNames=[], newPresent=[];
    for(let i = 0; i < newPupils.length; i++) {
      newNames.push(newPupils[i].name);
      newPresent.push(newPupils[i].present)
    }
    await updateDoc(doc(db, "shicheck", classCode), { names: newNames, present: newPresent });
  }
  const downloadPDF = async () => {
    const pdf = new jsPDF({ unit: "pt", format: "a4" });

    pdf.addFileToVFS("NotoSansArmenian.ttf", notoFontBase64);
    pdf.addFont("NotoSansArmenian.ttf", "NotoSansArmenian", "normal");
    pdf.setFont("NotoSansArmenian");

    const head = [["Երթուղի", "Անուն", "Ներկա/Բացակա"]];
    const body = classes.map(r => [r.id, r.name, r.present ? "Ներկա" : "Բացակա"]);

    autoTable(pdf, {
  head,
  body,
  margin: { top: 40 },
  styles: { font: "NotoSansArmenian", fontSize: 12 },
  headStyles: { 
    font: "NotoSansArmenian", 
    fontSize: 12, 
    fontStyle: 'normal' 
  }
});

    pdf.save("presence-list.pdf");
  }

  if(adminMode) {
    return (
      <>
        <Box display="flex" justifyContent="flex-end" mb={2} gap={1} style={{width: "90%"}}>
          <IconButton onClick={() => {downloadPDF()}} sx={{ backgroundColor: '#26b8b8', color: '#fff', '&:hover': { backgroundColor: '#1ea0a0' } }}>
            <DownloadIcon />
          </IconButton>
          <IconButton onClick={() => {onLogout(); setClassCode(""); 
            document.cookie = "classCode=noClass; path=/; max-age=3600;"}} sx={{ backgroundColor: '#26b8b8', color: '#fff', '&:hover': { backgroundColor: '#1ea0a0' } }}>
          <LogoutIcon />
        </IconButton>
        </Box>
        <Container
            component="main"
            style={{
              color: "white",
              width: "80%",
              backgroundColor: "#2fb5be",
              borderRadius: "20px",
              padding: "2%",
              marginBottom: "1%",
              marginTop: "2%" 
            }}
          >
            <CssBaseline />
            <Box>
              <TableContainer component={Paper}>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>Երթուղի</TableCell>
                      <TableCell>Անուն</TableCell>
                      <TableCell>Ներկա/Բացակա</TableCell>
                    </TableRow>
                  </TableHead>

                  <TableBody>
                    {classes.map((row, i) => (
                      <TableRow key={i}>
                        <TableCell>{row.id}</TableCell>
                        <TableCell>{row.name}</TableCell>
                        <TableCell>{row.present ? "Ներկա" : "Բացակա"}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            </Box>
          </Container>
      </>
    )
  }

  return (
    <>
      <Box display="flex" justifyContent="flex-end" mb={2} gap={1}>
        <IconButton onClick={() => {setPupilModalOpen(true); setSign("-");}} sx={{ backgroundColor: '#26b8b8', color: '#fff', '&:hover': { backgroundColor: '#1ea0a0' } }}>
          <RemoveIcon />
        </IconButton>
        <IconButton onClick={() => {setPupilModalOpen(true); setSign("+");}} sx={{ backgroundColor: '#26b8b8', color: '#fff', '&:hover': { backgroundColor: '#1ea0a0' } }}>
          <AddIcon />
        </IconButton>
        <IconButton onClick={() => {onLogout(); setClassCode(""); 
            document.cookie = "classCode=noClass; path=/; max-age=3600;"}} sx={{ backgroundColor: '#26b8b8', color: '#fff', '&:hover': { backgroundColor: '#1ea0a0' } }}>
          <LogoutIcon />
        </IconButton>
      </Box>
      <Grid container spacing={2}>        
        {pupils.map((pupil, i) => (
          <Grid item xs={6} key={i}>
            <Button
              style={{backgroundColor: !pupil.present ? "white" : "#26b8b8", color: pupil.present ? "white" : "#26b8b8"}}
              variant="outlined"
              fullWidth
              sx={{ py: 4, textTransform: 'none' }}
              onClick={() => handleButtonClick(i)}
            >
                <Typography variant="h6" component="div" sx={{ flexGrow: 1, textAlign: 'center' }}>
                  {pupil.name}
                </Typography>
            </Button>
          </Grid>
        ))}
      </Grid>
      <PupilModalDialog
        open={pupilModalOpen}
        onClose={() => setPupilModalOpen(false)}
        sign={sign}
        data={{pupils, setNewPupils}}
      />
    </>
  );
}